```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only a published digest has delivered its items; marking the
        // considered ids seen for an unpublished digest would drop them.
        if published.published {
            let mut ids = published.considered.clone();
            ids.sort();
            ids.dedup();

            for id in &ids {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I left out the enrichment fetch. The node's `with` clause grants only `aap:caps/state-rw@0.1.0`, so importing `http-client` would exceed its authority, and an external lookup would also make the output depend on something outside the node. If you want that enrichment, it needs its own node with an explicit `HTTPClient` grant for `metadata.internal.example`.

